        View handle=new View(owner);handle.setContentDescription("현재 곡 시트 손잡이");handle.setBackground(shape(muted,2));LinearLayout.LayoutParams grip=new LinearLayout.LayoutParams(dp(36),dp(4));grip.gravity=Gravity.CENTER;grip.bottomMargin=dp(8);root.addView(handle,grip);
        LinearLayout header=new LinearLayout(owner);header.setGravity(Gravity.CENTER_VERTICAL);TransportButton close=new TransportButton(owner,TransportButton.Kind.CLOSE,ink,0,"곡 정보 닫기",this::dismiss);header.addView(close,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView heading=text("NOW PLAYING",14,muted);heading.setGravity(Gravity.CENTER);heading.setTypeface(UiAssets.semibold(owner));heading.setLetterSpacing(.10f);header.addView(heading,new LinearLayout.LayoutParams(0,-2,1));TransportButton queue=new TransportButton(owner,TransportButton.Kind.QUEUE,ink,0,"재생 대기열",this::showQueue);header.addView(queue,new LinearLayout.LayoutParams(dp(48),dp(48)));root.addView(header);
