        LinearLayout hero=column();hero.setGravity(Gravity.CENTER);int size=Math.min(wide?320:300,Math.max(140,owner.getResources().getConfiguration().screenWidthDp-(wide?400:64)));art=new RoundedArtwork(owner,22);art.setScaleType(ImageView.ScaleType.CENTER_CROP);art.setBackground(shape(surface,22));art.setClipToOutline(true);art.setContentDescription("현재 곡 앨범 표지");hero.addView(art,new LinearLayout.LayoutParams(dp(size),dp(size)));
