        ScrollView infoScroll=new ScrollView(owner);LinearLayout identity=column();identity.setGravity(Gravity.BOTTOM);infoScroll.setFillViewport(true);infoScroll.addView(identity);if(wide)right.addView(infoScroll,new LinearLayout.LayoutParams(-1,-2));else right.addView(infoScroll,new LinearLayout.LayoutParams(-1,-2));
