        badge=text("",12,muted);badge.setPadding(dp(10),dp(8),dp(10),dp(8));badge.setBackground(shape(surface,8));identity.addView(badge);sourceInfo=text("",11,muted);sourceInfo.setGravity(wide?Gravity.START:Gravity.CENTER);identity.addView(sourceInfo);status=text("",12,muted);status.setVisibility(View.GONE);
        seek=new SeekBar(owner);seek.setContentDescription("재생 위치");seek.setProgressTintList(android.content.res.ColorStateList.valueOf(accent));seek.setThumbTintList(android.content.res.ColorStateList.valueOf(accent));right.addView(seek,new LinearLayout.LayoutParams(-1,dp(48)));seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){if(user)player.seekTo(p);}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});clock=text("0:00 / --:--",12,muted);clock.setFontFeatureSettings("tnum");right.addView(clock);
        LinearLayout controls=new LinearLayout(owner);controls.setGravity(Gravity.CENTER);controls.setPadding(0,dp(8),0,dp(8));right.addView(controls);
