        shuffle=addControl(controls,TransportButton.Kind.SHUFFLE,"셔플",48,()->{player.setShuffleModeEnabled(!player.getShuffleModeEnabled());settings.shuffle=player.getShuffleModeEnabled();settings.save();refresh();});
        addControl(controls,TransportButton.Kind.PREVIOUS,"이전 곡",48,()->player.seekToPreviousMediaItem());play=addControl(controls,TransportButton.Kind.PLAY,"재생",settings.playButtonDp,()->{if(player.getPlayWhenReady())player.pause();else{player.prepare();player.play();}});addControl(controls,TransportButton.Kind.NEXT,"다음 곡",48,()->player.seekToNextMediaItem());repeat=addControl(controls,TransportButton.Kind.REPEAT,"반복",48,()->{player.setRepeatMode((player.getRepeatMode()+1)%3);settings.repeat=player.getRepeatMode();settings.save();refresh();});
