        LinearLayout activity=column();activity.setPadding(dp(4),dp(4),dp(4),0);aiProgress=new ProgressBar(owner,null,android.R.attr.progressBarStyleHorizontal);aiProgress.setTag("smart-progress");aiProgress.setIndeterminate(true);aiProgress.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(muted));aiProgress.setAlpha(.35f);aiProgress.setVisibility(View.INVISIBLE);activity.addView(aiProgress,new LinearLayout.LayoutParams(-1,dp(2)));aiStatus=text("",10,muted);aiStatus.setTag("smart-note");aiStatus.setAlpha(.55f);aiStatus.setSingleLine(true);aiStatus.setEllipsize(android.text.TextUtils.TruncateAt.END);aiStatus.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);aiStatus.setMinHeight(dp(24));aiStatus.setContentDescription("AI 추천 상태 · 최근 기록 보기");aiStatus.setOnClickListener(v->new com.google.android.material.dialog.MaterialAlertDialogBuilder(getContext()).setTitle("AI · RECENT").setMessage(SmartStatus.history(owner)).setPositiveButton("닫기",null).show());LinearLayout notes=new LinearLayout(owner);notes.setGravity(Gravity.CENTER_VERTICAL);dataStatus=text("",10,muted);dataStatus.setAlpha(.55f);dataStatus.setSingleLine(true);dataStatus.setMaxWidth(dp(180));dataStatus.setEllipsize(android.text.TextUtils.TruncateAt.END);dataStatus.setMinHeight(dp(24));dataStatus.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);dataStatus.setContentDescription("데이터 사용 안내");dataStatus.setOnClickListener(v->{if(owner instanceof MainActivity)NetworkSettings.show((MainActivity)owner);});notes.addView(dataStatus,new LinearLayout.LayoutParams(-2,-2));notes.addView(aiStatus,new LinearLayout.LayoutParams(0,-2,1));activity.addView(notes);root.addView(activity);
        refresh();main.post(tick);
