    /** An opaque, stationary window backdrop prevents stale pixels when One UI moves the sheet. */
    private android.graphics.drawable.Drawable captureBackdrop(){
        View decor=owner.getWindow().getDecorView();int w=decor.getWidth(),h=decor.getHeight();if(w<=0||h<=0)return new android.graphics.drawable.ColorDrawable(bg);
        try{Bitmap bitmap=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(bg);decor.draw(canvas);canvas.drawColor(0x30000000);return new android.graphics.drawable.BitmapDrawable(owner.getResources(),bitmap);}catch(OutOfMemoryError e){return new android.graphics.drawable.ColorDrawable(bg);}
    }
    @Override public void show(){
        stableBackdrop=captureBackdrop();super.show();Window window=getWindow();
        window.setBackgroundDrawable(stableBackdrop);window.setFormat(android.graphics.PixelFormat.OPAQUE);window.clearFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);window.setWindowAnimations(0);
        View decor=window.getDecorView();android.widget.FrameLayout sheet=findViewById(com.google.android.material.R.id.design_bottom_sheet);
        if(sheet!=null){sheet.setBackgroundColor(Color.TRANSPARENT);android.graphics.Rect frame=new android.graphics.Rect();owner.getWindow().getDecorView().getWindowVisibleDisplayFrame(frame);sheet.getLayoutParams().height=Math.max(dp(300),frame.height()-dp(16));
            com.google.android.material.bottomsheet.BottomSheetBehavior<android.widget.FrameLayout> behavior=com.google.android.material.bottomsheet.BottomSheetBehavior.from(sheet);behavior.setState(com.google.android.material.bottomsheet.BottomSheetBehavior.STATE_EXPANDED);behavior.setSkipCollapsed(true);
            behavior.addBottomSheetCallback(new com.google.android.material.bottomsheet.BottomSheetBehavior.BottomSheetCallback(){public void onStateChanged(View view,int state){decor.invalidate();}public void onSlide(View view,float offset){decor.invalidate();if(view.getParent() instanceof View)((View)view.getParent()).invalidate();}});
        }
    }
    void openCurrentAlbum(){String id=song.optString("albumId");if(id.isEmpty()||!(owner instanceof MainActivity))return;try{JSONObject album=new JSONObject().put("id",id).put("name",song.optString("album")).put("artist",song.optString("artist")).put("coverArt",song.optString("coverArt"));dismiss();MainActivity activity=(MainActivity)owner;activity.tab="앨범";activity.openAlbum(album);}catch(JSONException ignored){}}
    void showQueue(){new QueueSheet(owner,player,client,covers,ink,muted,bg,surface,accent).show();}
    void showTags(){LinearLayout content=column();content.setPadding(dp(20),dp(8),dp(20),dp(8));for(Map.Entry<String,String> row:SongMetadata.rows(song).entrySet()){content.addView(text(row.getKey(),12,muted));TextView value=text(row.getValue(),15,ink);value.setTextIsSelectable(true);value.setPadding(0,0,0,dp(12));content.addView(value);}content.addView(text(status.getText().toString(),12,muted));ScrollView scroll=new ScrollView(owner);scroll.addView(content);new com.google.android.material.dialog.MaterialAlertDialogBuilder(getContext()).setTitle("INFO").setView(scroll).setNeutralButton("새로고침",(d,w)->load(true)).setPositiveButton("닫기",null).show();}
    TransportButton addControl(LinearLayout group,TransportButton.Kind kind,String label,int size,Runnable action){boolean primary=kind==TransportButton.Kind.PLAY;TransportButton b=new TransportButton(owner,kind,primary?(settings.dark?0xff101820:0xffffffff):ink,primary?accent:Color.TRANSPARENT,label,action);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(size),dp(size));if(group.getChildCount()>0)lp.setMarginStart(dp(settings.playerGapDp));group.addView(b,lp);return b;}
    void refresh(){if(closed||seek==null)return;MediaItem item=player.getCurrentMediaItem();String id=item==null?"":item.mediaId;
        if(!id.equals(trackId)||boundApi!=client.get())load(false);
        NetworkUsage usage=NetworkUsage.get(owner);usage.sample(false);boolean raw=item!=null&&(item.mediaMetadata.extras==null||!item.mediaMetadata.extras.getBoolean("transcoded",false));String dataNote=!usage.prefs.getBoolean("warnings",true)?"":usage.overLimit()?"DATA · 경고 기준 도달":usage.metered?raw?"DATA · 192 kbps 권장":"DATA · 사용량 보기":"";if(!dataNote.contentEquals(dataStatus.getText()))dataStatus.setText(dataNote);dataStatus.setVisibility(dataNote.isEmpty()?View.GONE:View.VISIBLE);
        android.content.SharedPreferences smart=SmartPlayback.settings(owner);boolean working=smart.getBoolean("refillBusy",false)&&smart.getBoolean("autoplay",false);String note=SmartSession.scope.equals(smart.getString("statusScope",""))?smart.getString("status",""):"";String noteLine=working?"AI · 추천 중…":!smart.getBoolean("autoplay",false)?"AI · OFF":note.isEmpty()||note.equals("다음 곡 추천 중")?"AI · 대기":"AI · "+note;if(!noteLine.contentEquals(aiStatus.getText()))aiStatus.setText(noteLine);int visibility=working?View.VISIBLE:View.INVISIBLE;if(aiProgress.getVisibility()!=visibility)aiProgress.setVisibility(visibility);
        play.setPlaying(player.getPlayWhenReady());play.setBuffering(player.getPlaybackState()==Player.STATE_BUFFERING);shuffle.setAlpha(player.getShuffleModeEnabled()?1f:.45f);repeat.setAlpha(player.getRepeatMode()==Player.REPEAT_MODE_OFF?.45f:1f);repeat.setContentDescription(player.getRepeatMode()==Player.REPEAT_MODE_ONE?"한 곡 반복":player.getRepeatMode()==Player.REPEAT_MODE_ALL?"전체 반복":"반복 안 함");play.setEnabled(item!=null);QualityInfo quality=AudioQuality.get(player);String qualityKey=settings.indicatorMode+"|"+quality.color+"|"+quality.label;if(!qualityKey.equals(badge.getTag())){badge.setTag(qualityKey);android.text.SpannableString line=new android.text.SpannableString("● "+quality.label);line.setSpan(new android.text.style.ForegroundColorSpan(quality.color),0,1,android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);badge.setText(line);badge.setTextColor(ink);badge.setBackground(GlassUi.panel(owner,settings.dark,18,90));badge.setGravity(Gravity.CENTER);}long duration=PlaybackInfo.duration(player),position=player.getCurrentPosition();int max=(int)Math.min(Integer.MAX_VALUE,Math.max(1,duration)),progress=(int)Math.min(Integer.MAX_VALUE,position);
        if(seek.getMax()!=max)seek.setMax(max);if(seek.getProgress()!=progress)seek.setProgress(progress);seek.setEnabled(duration>0);String value=SongMetadata.duration(position/1000)+" / "+(duration>0?SongMetadata.duration(duration/1000):"--:--");if(!clock.getText().toString().equals(value))clock.setText(value);
    }
    void load(boolean force){
        MediaItem item=player.getCurrentMediaItem();String id=item==null?"":item.mediaId;Api active=client.get();if(!force&&id.equals(trackId)&&boundApi==active)return;
        trackId=id;boundApi=active;int task=++request;MediaMetadata meta=player.getMediaMetadata();JSONObject snapshot=new JSONObject();
        try{if(meta.extras!=null)snapshot=new JSONObject(meta.extras.getString(SongMetadata.EXTRA,"{}"));if(meta.title!=null)snapshot.put("title",meta.title.toString());if(meta.artist!=null)snapshot.put("artist",meta.artist.toString());if(meta.albumTitle!=null)snapshot.put("album",meta.albumTitle.toString());}catch(JSONException ignored){}
        song=SongMetadata.safe(snapshot);render();if(active!=null&&!song.optString("coverArt").isEmpty())covers.bind(art,active,song.optString("coverArt"),720);else covers.bindMedia(art,meta,720);covers.bindMedia(backdrop,meta,320);
        if(id.isEmpty()){status.setText("재생 중인 곡이 없습니다");return;}
        if(active==null){status.setText("");return;}
        status.setText("");
        io.execute(()->{try{JSONObject result=active.call("getSong","id",id).optJSONObject("song");main.post(()->{if(closed||task!=request||active!=client.get()||!id.equals(currentId()))return;song=SongMetadata.merge(song,result);status.setText("");render();covers.bind(art,active,song.optString("coverArt"),720);});}catch(Exception ignored){main.post(()->{if(!closed&&task==request&&active==client.get()&&id.equals(currentId()))status.setText("추가 정보 조회 실패");});}});
    }
    private String currentId(){MediaItem item=player.getCurrentMediaItem();return item==null?"":item.mediaId;}
    private void render(){title.setText(song.optString("title","음악을 선택하세요"));String artist=SongMetadata.names(song,"artists","artist"),album=song.optString("album","");summary.setText(artist+" · "+SongMetadata.year(song));albumLink.setText(album);albumLink.setEnabled(!song.optString("albumId").isEmpty());java.util.List<String> technical=new java.util.ArrayList<>();if(!song.optString("suffix").isEmpty())technical.add(song.optString("suffix").toUpperCase(java.util.Locale.ROOT));if(song.optInt("bitDepth")>0)technical.add(song.optInt("bitDepth")+"bit");if(song.optInt("samplingRate")>0)technical.add(String.format(java.util.Locale.ROOT,"%.1f kHz",song.optInt("samplingRate")/1000.0));if(song.optInt("bitRate")>0)technical.add(song.optInt("bitRate")+" kbps");sourceInfo.setText("SOURCE · "+(technical.isEmpty()?"정보 없음":String.join(" · ",technical)));}

    void release(){if(!closed){closed=true;request++;main.removeCallbacksAndMessages(null);io.shutdownNow();}}
    @Override public void cancel(){release();super.cancel();}
    @Override public void dismiss(){release();super.dismiss();}
